"""pose 키포인트 기반 방향/악수 추정 (휴리스틱).

ultralytics YOLO-pose 의 키포인트는 COCO 17개 포맷이며, 각 점은 (x, y, conf).
인덱스:
  0 nose, 1 left_eye, 2 right_eye, 3 left_ear, 4 right_ear,
  5 left_shoulder, 6 right_shoulder, 7 left_elbow, 8 right_elbow,
  9 left_wrist, 10 right_wrist, 11 left_hip, 12 right_hip,
  13 left_knee, 14 right_knee, 15 left_ankle, 16 right_ankle

주의: COCO 의 left/right 는 '사람 기준' 좌우다. 정면(카메라를 바라봄)일 때
사람의 오른어깨(6)는 이미지의 왼쪽(작은 x)에 나타난다.

단일 카메라 기반이라 모두 근사값이다.
"""

import math

NOSE, LEYE, REYE, LEAR, REAR = 0, 1, 2, 3, 4
LSH, RSH, LEL, REL, LWR, RWR = 5, 6, 7, 8, 9, 10
LHIP, RHIP = 11, 12


def _vis(kps, i, conf_th):
    return kps[i][2] >= conf_th


def _dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def estimate_facing(kps, bbox, conf_th=0.3):
    """사람이 향한 방향을 추정: 'front' | 'back' | 'left' | 'right' | 'unknown'.

    얼굴(코·눈) 가시성을 1순위로 본다 — 대화 의도(front) 판정에 가장 안정적.
    어깨는 보조로 측면/후면 판별에 쓰되, 일부만 보여도 최대한 판정한다.
    """
    x1, y1, x2, y2 = bbox
    bbox_w = max(1.0, x2 - x1)

    nose_v = _vis(kps, NOSE, conf_th)
    face_pts = sum(_vis(kps, i, conf_th) for i in (NOSE, LEYE, REYE))
    lsh_v, rsh_v = _vis(kps, LSH, conf_th), _vis(kps, RSH, conf_th)

    # 1) 양 어깨가 보이고 x 간격이 좁으면 측면 -> 코/귀로 좌우
    if lsh_v and rsh_v:
        lsh, rsh = kps[LSH], kps[RSH]
        dx = lsh[0] - rsh[0]
        if abs(dx) / bbox_w < 0.20:                    # 측면
            center_x = (lsh[0] + rsh[0]) / 2.0
            if nose_v:
                return 'left' if kps[NOSE][0] < center_x else 'right'
            if _vis(kps, LEAR, conf_th) and not _vis(kps, REAR, conf_th):
                return 'left'
            if _vis(kps, REAR, conf_th) and not _vis(kps, LEAR, conf_th):
                return 'right'
            return 'side'
        # 정면/후면
        if face_pts >= 1:
            return 'front'
        return 'back'

    # 2) 어깨 정보가 부족하면 얼굴 가시성으로 판정
    if face_pts >= 1:
        return 'front'                                  # 얼굴 보임 = 정면
    # 얼굴이 전혀 안 보이는데 몸 일부라도 잡히면 후면으로 간주
    if lsh_v or rsh_v or _vis(kps, LEAR, conf_th) or _vis(kps, REAR, conf_th):
        return 'back'
    return 'unknown'


def _hand_offered(kps, el_i, wr_i, conf_th):
    """팔뚝(팔꿈치-손목)이 대체로 수평이면 손 내민 것으로 본다 (관대).

    골반/키 기준이 아니라 팔뚝 방향만 보므로 서서/앉아서 모두 동일하게 동작.
    팔을 내리면 팔뚝이 수직(손목이 팔꿈치 아래)이라 제외되고,
    앞/옆으로 뻗으면 수평에 가까워져 잡힌다.
    (YOLO-pose 는 손가락/손모양 키포인트가 없어 손목 위치까지만 사용)
    """
    if not (_vis(kps, el_i, conf_th) and _vis(kps, wr_i, conf_th)):
        return False
    el, wr = kps[el_i], kps[wr_i]
    fore = _dist(el, wr)
    if fore < 1e-3:
        return False
    horiz = abs(wr[1] - el[1]) / fore   # 0=수평, 1=수직(내린 팔)
    return horiz < 0.6


def detect_handshake_ready(kps, conf_th=0.3):
    """양팔 중 하나라도 팔뚝이 뻗은(수평) 자세이면 True (관대한 근사).

    한계: 단일 카메라 2D + 손목까지만. 손모양/실제 악수 성립은 판정 못 함.
    depth 카메라가 있으면(손이 몸보다 앞) 훨씬 정확해진다.
    """
    right = _hand_offered(kps, REL, RWR, conf_th)
    left = _hand_offered(kps, LEL, LWR, conf_th)
    return bool(right or left)
